def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)  # Integer division performs floor
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in [1, 2, 3, 4, 5]:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {'S(N)': S_N, 'T(N)': T_N}

print("N | S(N) | T(N)")
for N, res in results.items():
    print(f"{N} | {res['S(N)']} | {res['T(N)']}")

